import * as THREE from 'three/webgpu';
import { texture, uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-collection-card-1-label';
  group.position.set(-3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const rectW = 512, rectH = 320, atlasW = 512, atlasH = 320;
  const aspect = rectW / rectH;
  const planeH = 0.5;
  const planeW = planeH * aspect;

  const geometry = new THREE.PlaneGeometry(planeW, planeH);

  const map = ctx.textureLoader.load(config.assets?.imageUrl || '/prism-mock/home/nodes/floating-accent.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const offsetX = 0 / atlasW;
  const offsetY = 0 / atlasH;
  const repeatX = rectW / atlasW;
  const repeatY = rectH / atlasH;

  const uvNode = uv().mul(vec2(repeatX, repeatY)).add(vec2(offsetX, offsetY));

  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });
  material.colorNode = texture(map, uvNode);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'card-image';
  group.add(mesh);

  // Billboard behavior: continually face camera via onBeforeRender
  mesh.onBeforeRender = (renderer, scene, camera) => {
    group.quaternion.copy(camera.quaternion);
  };

  // Text content: headline "Collection 1"
  let textMesh = null;
  if (ctx.fontAtlas && ctx.fontAtlas.createText) {
    textMesh = ctx.fontAtlas.createText({
      text: 'Collection 1',
      font: 'Lora',
      weight: 400,
      size: 0.34,
      color: config.visual?.colors?.paper || '#e8ecf2',
    });
    textMesh.name = 'headline-text';
    textMesh.position.set(-planeW / 2 + 0.06, -planeH / 2 + 0.08, 0.01);
    group.add(textMesh);
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    if (textMesh) {
      textMesh.geometry?.dispose?.();
      textMesh.material?.dispose?.();
    }
  };

  return group;
}
